import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CCXDMzJr.js";const p=JSON.parse('{"title":"第 21 章 最佳实践与调试","description":"","frontmatter":{},"headers":[],"relativePath":"ch21-plugin-best-practices.md","filePath":"ch21-plugin-best-practices.md","lastUpdated":null}'),c={name:"ch21-plugin-best-practices.md"};function l(r,e,i,s,n,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="第-21-章-最佳实践与调试" tabindex="-1">第 21 章 最佳实践与调试 <a class="header-anchor" href="#第-21-章-最佳实践与调试" aria-label="Permalink to &quot;第 21 章 最佳实践与调试&quot;">​</a></h1><h2 id="_21-1-设计原则" tabindex="-1">21.1 设计原则 <a class="header-anchor" href="#_21-1-设计原则" aria-label="Permalink to &quot;21.1 设计原则&quot;">​</a></h2><h3 id="就近原则-placement" tabindex="-1">就近原则（Placement） <a class="header-anchor" href="#就近原则-placement" aria-label="Permalink to &quot;就近原则（Placement）&quot;">​</a></h3><p>&quot;新行为放哪里&quot;的第一问是<strong>数据与能力在哪个平面</strong>：</p><ol><li>数据在 Host（文件、进程、会话）→ Host 处理，需要展示时经最小 JSON 过桥；</li><li>数据已在 Slot props（会话快照、工作区列表）→ 直接用 props，不加 RPC；</li><li>只改自己组件的样式 → <code>styles.insert</code> + <code>--dsw-*</code> 变量；只有全局品牌才覆盖主题 token；</li><li>只差一个小入口 → 找最窄的 Slot（<code>sidebar.footer.action</code>、<code>tool.view.cordis</code>），不要替换整个 sidebar/root。</li></ol><h3 id="事件优先于硬编码" tabindex="-1">事件优先于硬编码 <a class="header-anchor" href="#事件优先于硬编码" aria-label="Permalink to &quot;事件优先于硬编码&quot;">​</a></h3><ul><li>拦截与策略用事件（waterfall/serial），直接能力调用用服务方法；</li><li>观察用 <code>emit</code>/<code>parallel</code>，决策用 <code>bail</code>/<code>serial</code>，包裹用 <code>waterfall</code>；</li><li><strong>给事件选对域</strong>：持久事实 → <code>SessionEventMap</code>（可重建）；在途观察 → <code>agent/*</code>；接缝策略 → <code>tools/*</code>/<code>fs/*</code>。</li></ul><h3 id="模型可见即已记录" tabindex="-1">模型可见即已记录 <a class="header-anchor" href="#模型可见即已记录" aria-label="Permalink to &quot;模型可见即已记录&quot;">​</a></h3><p>任何要进模型的内容：</p><ul><li>用 <code>agent.inject()</code>（持久、不唤醒）或 <code>user/message</code> 的插件 source；</li><li>不要绕过日志直接改消息——循环从日志重建请求，绕过即丢失；</li><li>新模型可见输入 = 新会话事件类型（声明合并 <code>SessionEventMap</code> + 从日志渲染）。</li></ul><h3 id="可逆性与所有权" tabindex="-1">可逆性与所有权 <a class="header-anchor" href="#可逆性与所有权" aria-label="Permalink to &quot;可逆性与所有权&quot;">​</a></h3><ul><li>每个注册都从 <code>ctx.effect()</code>/<code>ctx.on()</code>/服务返回的 disposer 获得清理；</li><li>清理顺序重要的相关工作放<strong>同一个</strong> effect（generator 逐个 yield）；</li><li>持有外部订阅时用 <code>ctx.effect(() =&gt; subscribe(...))</code> 并确保 subscribe 返回 disposer；</li><li>不要假设卸载会自动清理任意第三方回调。</li></ul><h2 id="_21-2-数据纪律" tabindex="-1">21.2 数据纪律 <a class="header-anchor" href="#_21-2-数据纪律" aria-label="Permalink to &quot;21.2 数据纪律&quot;">​</a></h2><h3 id="内部活数据不可序列化" tabindex="-1">内部活数据不可序列化 <a class="header-anchor" href="#内部活数据不可序列化" aria-label="Permalink to &quot;内部活数据不可序列化&quot;">​</a></h3><p><code>Session</code>、<code>Agent</code>、<code>ToolExecution</code>、Slot props 等是<strong>内部活数据</strong>，不是普通 JSON：</p><ul><li>禁止 <code>JSON.stringify</code>/<code>structuredClone</code> 整个对象或递归枚举；</li><li>只读任务需要的叶子字段（字符串/数字/布尔），构造<strong>最小自有数据对象</strong>；</li><li>RPC 参数与返回值必须无损 JSON（禁函数/React 元素/类实例/服务实例）；无数据返回 <code>null</code>。</li></ul><h3 id="深冻结是保护不是负担" tabindex="-1">深冻结是保护不是负担 <a class="header-anchor" href="#深冻结是保护不是负担" aria-label="Permalink to &quot;深冻结是保护不是负担&quot;">​</a></h3><p>会话事件、派生消息、请求配置在写入时冻结——不要试图改写它们；需要&quot;新值&quot;就追加新事件（<code>replace</code> 表面操作由框架执行）。</p><h2 id="_21-3-性能要点" tabindex="-1">21.3 性能要点 <a class="header-anchor" href="#_21-3-性能要点" aria-label="Permalink to &quot;21.3 性能要点&quot;">​</a></h2><ol><li><strong>热路径零分配</strong>：事件载波（scope carrier）构造一次复用；<code>agent/inbox/spliced</code> 等先落盘再广播，观察者读到的列表仍是切除前视图；</li><li><strong>增量折叠</strong>：<code>deriveMessages</code>/<code>requestHeader</code> 每节点只投影一次（缓存），增量消费用 <code>replaceGeneration</code> 区分尾部增长与重写；</li><li><strong>读不建层</strong>：scope 的 <code>ScopedLayers</code> 读操作不创建 exact-scope 层，整层空时回收；</li><li><strong>批量通知</strong>：Slot <code>subscribe</code> 变更按微任务批量（同 tick N 个变更 = 一个通知）；</li><li><strong>避免重复注入</strong>：runtime-context 投影只在内容真正变化时才注入新快照（diffing），空时注入 CLEARED 标记。</li></ol><h2 id="_21-4-防御性编写" tabindex="-1">21.4 防御性编写 <a class="header-anchor" href="#_21-4-防御性编写" aria-label="Permalink to &quot;21.4 防御性编写&quot;">​</a></h2><ul><li><strong>fail loud</strong>：配置坏、依赖缺、契约违反——尽早抛清晰错误，绝不静默降级（dsh 的启动审计、append 校验、sweep 补偿都是这个哲学的体现）；</li><li><strong>不信任上游输入</strong>：模型生成的工具参数、插件可控的字符串（boot 清单里的 <code>&lt;</code> 转义）、客户端 payload——按外部输入处理；</li><li><strong>取消要响应</strong>：<code>exec.signal</code>/<code>task.signal</code> 触发时取消在途工作；发布到 jobs 的任务生命周期归任务控制器；</li><li><strong>呈现器必须纯</strong>：<code>presentCall</code>/<code>presentResult</code> 在实时与重放两条路径运行——无 I/O、无会话读取、无时钟；防重放崩溃用 <code>defineTool</code> 的软校验（畸形参数返回 undefined 而非 throw）。</li></ul><h2 id="_21-5-调试工具链" tabindex="-1">21.5 调试工具链 <a class="header-anchor" href="#_21-5-调试工具链" aria-label="Permalink to &quot;21.5 调试工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>cordis_inspect_self(pluginId, packageId)</code></td><td>读 Package 源码与运行诊断（消息 + 栈）</td></tr><tr><td><code>fiber.getEffects()</code></td><td>看插件注册了哪些带标签的 effect（诊断树）</td></tr><tr><td><code>internal/status</code> 事件</td><td>观察 fiber 状态迁移时序</td></tr><tr><td><code>ctx.logger(name)</code></td><td>命名日志（<code>dsh</code> 前缀、按服务过滤）</td></tr><tr><td><code>dsh --profile web --dump-config</code></td><td>看组合后的配置树（哪些行被谁 patch）</td></tr><tr><td><code>docs/subsystems/*</code> 的 cordis-catalog</td><td>精确服务/事件签名（生成自源码）</td></tr><tr><td><code>docs/event-producer-consumer.md</code></td><td>事件生产者/消费者目录</td></tr><tr><td><code>docs/tool-catalog.md</code> / <code>docs/persistence-catalog.md</code></td><td>工具与持久化事件目录</td></tr></tbody></table><h3 id="常见启动失败速查" tabindex="-1">常见启动失败速查 <a class="header-anchor" href="#常见启动失败速查" aria-label="Permalink to &quot;常见启动失败速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>症状</th><th>原因与位置</th></tr></thead><tbody><tr><td><code>plugin(s) failed to load: x</code></td><td>模块解析失败（<code>assertEntriesLoaded</code>）</td></tr><tr><td><code>N entries did not activate</code> + <code>pending (waiting for services: ...)</code></td><td>依赖服务从未出现（<code>assertEntriesActivated</code>）</td></tr><tr><td><code>dsh: fatal load failure: ...</code></td><td>启动后未捕获 rejection（<code>installFailLoud</code>）</td></tr><tr><td><code>service &quot;x&quot; has been registered at &lt;fiber&gt;</code></td><td>同作用域重复提供服务</td></tr><tr><td><code>cannot get property &quot;x&quot; without inject</code></td><td>未声明 inject 读取 ctx 属性</td></tr></tbody></table><h2 id="_21-6-测试" tabindex="-1">21.6 测试 <a class="header-anchor" href="#_21-6-测试" aria-label="Permalink to &quot;21.6 测试&quot;">​</a></h2><ul><li>工具/服务：vitest 单元测试，参照各包 <code>tests/</code>（mock adapter、contract-regression 等模式）；</li><li>插件：用 <code>packages/test-support</code> 的工具（llm-mock-server 等）做集成测试；</li><li>e2e：真实 API 测试需 <code>DEEPSEEK_API_KEY</code>（未设置自跳过）；</li><li>快照：<code>DSH_SNAPSHOT=record|refresh|replay</code>；</li><li>Web：<code>pnpm run test:web</code>（基于构建产物）。</li></ul><h2 id="_21-7-发布与兼容" tabindex="-1">21.7 发布与兼容 <a class="header-anchor" href="#_21-7-发布与兼容" aria-label="Permalink to &quot;21.7 发布与兼容&quot;">​</a></h2><ul><li>项目处于 developer preview：<strong>破坏性变更是预期内</strong>，升级前阅读 CHANGELOG 与文档；</li><li>插件包建议加 <code>dsh-plugin</code> topic 提高可发现性；</li><li>包间依赖用 <code>peerDependencies</code> 表达（与仓库约定一致）；</li><li>若修改了官方文档化的公开 API，同步更新 README/JSDoc（仓库有 verify 门禁）。</li></ul><h2 id="_21-8-小结" tabindex="-1">21.8 小结 <a class="header-anchor" href="#_21-8-小结" aria-label="Permalink to &quot;21.8 小结&quot;">​</a></h2><ul><li>就近原则：数据在哪、能力在哪、入口多窄，三层就近；</li><li>事件按域选择；模型可见即已记录；</li><li>活数据最小化、JSON 边界干净；</li><li>fail loud、信任边界清晰、取消响应、呈现纯函数；</li><li>用好 inspect/诊断/目录三件套，启动失败速查表对号入座。</li></ul><p>至此本书正文结束。附录提供命令速查、术语表与参考资源。</p>',33)])])}const g=t(c,[["render",l]]);export{p as __pageData,g as default};
